def copy_team_marks_to_students(apps, schema_editor):
    """Each existing team mark becomes the mark of every current team member."""
    Evaluation = apps.get_model("evaluations", "Evaluation")
    StudentMark = apps.get_model("evaluations", "StudentMark")
    TeamMember = apps.get_model("teams", "TeamMember")
    rows = []
    for ev in Evaluation.objects.select_related("assignment").iterator():
        ev.default_marks = ev.marks
        ev.save(update_fields=["default_marks"])
        for student_id in TeamMember.objects.filter(team_id=ev.assignment.team_id).values_list("student_id", flat=True):
            rows.append(StudentMark(evaluation_id=ev.id, student_id=student_id, marks=ev.marks))
    StudentMark.objects.bulk_create(rows)


